import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    keep = [True] * n
    st = []
    for i, c in enumerate(s):
        if c == '(':
            st.append(i)
        elif c == ')':
            if st:
                st.pop()
            else:
                keep[i] = False
    for i in st:
        keep[i] = False
    print(''.join(c for i, c in enumerate(s) if keep[i]))

